import re
def auto():
    seen = {}
    def visit(v, prov):
        if isinstance(v, str) and re.match(r"^(org|person|auth):", v) and v not in done and v not in seen:
            seen[v] = prov
    for kind in ("roles", "loans", "flows", "facts", "events"):
        for r in ROWS[kind]:
            for key in ("holder", "org", "lender", "borrower", "from", "to", "entity"):
                visit(r.get(key), r["prov"])
            for p_ in r.get("parties", []):
                visit(p_, r["prov"])
    for id_, prov in seen.items():
        typ = {"org": "Company", "person": "Person", "auth": "Authority"}[id_.split(":")[0]]
        label = AUTH.get(id_) or LABEL.get(id_) or PNAME.get(id_) or id_.split(":")[1].replace("-", " ").title()
        pv = dict(prov); pv["quote"] = ""; pv["note"] = "Stub entity: label only; first source in which the press contributor met this entity. " + ("Name derived from id slug." if label == id_.split(":")[1].replace("-", " ").title() else "")
        ent(id_, typ, label, pv, [], "Named in press/rating sources on the Ueno Bank case; see roles/flows rows." if typ != "Authority" else "Authority.",
            "Nombrado en fuentes de prensa/calificadoras sobre el caso Ueno Bank; ver filas de roles/flujos." if typ != "Authority" else "Autoridad.")
auto()
